from flask import Flask, jsonify

from widgets.catalog import list_widgets, get_widget

app = Flask(__name__)


@app.route('/')
def root():
    return jsonify({'service': 'widget-service'})


@app.route('/widgets')
def widgets_index():
    return jsonify({'widgets': list_widgets()})


@app.route('/widgets/<int:widget_id>')
def widget_detail(widget_id: int):
    w = get_widget(widget_id)
    if w is None:
        return jsonify({'error': 'not found'}), 404
    return jsonify(w)


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)

