import time

_WIDGETS = [
    {'id': 1, 'name': 'sprocket', 'price_cents': 199},
    {'id': 2, 'name': 'flange',   'price_cents': 449},
    {'id': 3, 'name': 'gizmo',    'price_cents': 1299},
]

_CACHE = {}
_CACHE_TTL_S = 30


def _now():
    return time.time()


def list_widgets():
    return list(_WIDGETS)


def get_widget(widget_id: int, _retries: int = 1):
    cached = _CACHE.get(widget_id)
    if cached and (_now() - cached['ts']) < _CACHE_TTL_S:
        return cached['value']
    for w in _WIDGETS:
        if w['id'] == widget_id:
            _CACHE[widget_id] = {'value': w, 'ts': _now()}
            return w
    if _retries > 0:
        return get_widget(widget_id, _retries=_retries - 1)
    return None
